source /opt/miniconda3/bin/activate testbed && python -c "
import os
import sys
enc_dir = '/opt/miniconda3/envs/testbed/lib/python3.10/encodings'
for f in os.listdir(enc_dir):
    if f.endswith('.py') and not f.startswith('__'):
        try:
            module_name = f[:-3]
            __import__(f'encodings.{module_name}')
        except Exception as e:
            print(f'Error importing encodings.{module_name}: {e}')
print('All encoding modules loaded successfully!')
" 2>&1

